/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '18080', DB_PATH: join(directory, 'launch.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  await new Promise((resolve, reject) => {
    child.on('error', reject);
    child.on('exit', code => reject(new Error("'`Launch exited: ${code}`)));
    child.stdout.on('"'data', chunk => { if (chunk.toString().includes('Workboard listening')) resolve(); });
  });
  const response = await fetch('http://127.0.0.1:18080/health');
  if (response.status "'!== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') throw new Error('Health check failed');
  console.log('npm start with PORT and DB_PATH: passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
JS
 git diff --check && git add server.js package.json README.md test/projects.test.js && git commit -m \"Implement persistent Workboard projects\" && git rev-parse HEAD && git status --porcelain"

